const k2 = cap(), x2 = await TR.command(["--circuit", "fish", "--runs", "1", "--write", "--out", "out.json"], { ...k2.io, run: () => no });
ok("!! with --write and a champion that does not qualify, the exit is 1, it says 'not written' and why, and it writes NOTHING", x2 === 1 && Object.keys(k2.files).length === 0 && k2.lines.some((l) => /^not written: held-out score does not beat/.test(l)));
const k3 = cap(), x3 = await TR.command(["--circuit", "fish", "--runs", "1", "--write", "--out", "out.json"], { ...k3.io, run: () => yes });
const wrote = k3.files["out.json"] ? JSON.parse(k3.files["out.json"]) : null;
ok("!! with --write and a champion that qualifies it writes ONE file, the --out one, a swek-brain-v1 blob wired to the fish, and says what it wrote (the count and the weights' hash)", x3 === 0 && Object.keys(k3.files).join() === "out.json" && wrote && wrote.format === "swek-brain-v1" && wrote.circuit === "fish" && k3.lines.some((l) => /^wrote out\.json: 803 weights, hash /.test(l)) && k3.lines.some((l) => l.includes(weightsHash(PF.FISH.handWeights()))));
const k4 = cap(), x4 = await TR.command(["--circuit", "fish", "--runs", "1", "--dump", "dump.json"], { ...k4.io, run: () => no });
const dumped = k4.files["dump.json"] ? JSON.parse(k4.files["dump.json"]) : null;
ok("--dump writes the dump file (and only that) even though the champion does not qualify", x4 === 0 && Object.keys(k4.files).join() === "dump.json" && dumped && dumped.verdict.ok === false && dumped.champion === 6101 && dumped.recipe.circuit === "fish");
const trained = { run: () => { throw new Error("a bad argument reached the training"); } };   // a parser that lets a typo through would otherwise train the default recipe, for hours
const k5 = cap(), x5 = await TR.command(["--bogus"], { ...k5.io, ...trained }).catch((e) => e.message), x6 = await TR.command(["--runs"], { ...cap().io, ...trained }).catch((e) => e.message);
ok("a bad argument returns 2 before any training and names the option", x5 === 2 && x6 === 2 && k5.err.length === 1 && /unknown option "--bogus"/.test(k5.err[0]) && /^trainPilotSub: /.test(k5.err[0]));
const k7 = cap(), x7 = await TR.command(["--circuit", "fish", "--one", "0", "--runs", "2", "--iters", "4", "--slice", "7"], k7.io), line7 = k7.lines.find((l) => l.startsWith("SEARCH "));
ok("--one K in the command prints the search as the SEARCH line the parent reads, the same weights as searchOne()", x7 === 0 && line7 && JSON.parse(line7.slice(7)).weights.every((v, i) => v === inproc.weights[i]) && differs(inproc.weights) > 0 && JSON.parse(line7.slice(7)).seed === 6100);
const k8 = cap(); let seen = null;
const x8 = await TR.command(["--circuit", "fish", "--runs", "2", "--iters", "4", "--slice", "7", "--workers", "2", "--quiet"], { ...k8.io, finish: (opts, runs) => { seen = runs; return no; } });
ok("!! `--workers 2` runs each search in its OWN PROCESS (and hands each the circuit and the --slice it was given) and finish() gets what those searches found: search 0 and search 1, the same bits and the same train scores as the in-process ones, in run order", x8 === 0 && seen && seen.length === 2 && seen[0].seed === 6100 && seen[1].seed === 6101 && seen[0].weights.every((v, i) => v === inproc.weights[i]) && seen[1].weights.every((v, i) => v === inproc1.weights[i]) && differs(seen[0].weights) > 0 && near(seen[0].trainScore, inproc.trainScore, 1e-12) && near(seen[1].trainScore, inproc1.trainScore, 1e-12) && k8.lines.length === 0);
const cli = spawnSync(process.execPath, [tool, "--bogus"], { encoding: "utf8", timeout: 20000 });
ok("the command file exits with the code the command returns: an unknown option exits 2 before any training", cli.status === 2 && /unknown option/.test(cli.stderr), cli.stderr.trim().slice(0, 80));

sec("8. the file it writes");
const fishBlob = TR.blobOf(yes, { runs: 4, iters: 400, seed: 6100, sigma: 0.3, maxK: 4, circuit: "fish" });
const imp = PB.importBrain(PB.describePolicy("pilotSubFish", { ...PF.FISH, id: "pilotSubFish", WEIGHT_COUNT: 803 }), fishBlob);
